<script setup lang="ts">import{computed}from'vue';const props=defineProps<{value?:string}>();const labels:Record<string,string>={queued:'Na fila',uploading:'Recebendo',processing:'Processando',retrying:'Nova tentativa',cancelling:'Cancelando',cancelled:'Cancelada',superseded:'Substituída',completed:'Concluída',failed:'Falhou',published:'Publicado',draft:'Rascunho',valid:'Válido',open:'Aberta',in_review:'Em revisão',resolved:'Resolvida',dismissed:'Descartada',critical:'Crítica',high:'Alta',medium:'Média',low:'Baixa',exact:'Exata',indicative:'Indicativa',in_stock:'Em estoque/sem saída',missing_input:'Entrada ausente',insufficient_quantity_data:'Quantidade insuficiente',insufficient_input_quantity:'Entradas insuficientes',review_identity:'Revisar correspondência',negative_margin:'Margem negativa',zero_margin:'Margem zero',reconciled:'Conciliado',reconciled_estimate:'Estimativa conciliada'};const label=computed(()=>labels[props.value||'']||props.value||'—')</script><template><span class="badge" :class="`badge-${value||'unknown'}`">{{label}}</span></template>
